/** Baseline availability of CSS features, from Biome 2.6.4 (`biome_css_analyze::baseline_data`). */

/** `l`imited, `n`ewly or `w`idely available, with the year it became newly available if known. */
export interface Baseline {
    tier: "limited" | "newly" | "widely";
    year: number | null;
}

const tiers = { l: "limited", n: "newly", w: "widely" } as const;

/** Reads `name tier year` entries separated by `;`. */
const table = (data: string): Map<string, Baseline> =>
    new Map(
        data.split(";").map((entry) => {
            const [name = "", tier = "w", year = ""] = entry.split(" ");
            return [
                name,
                {
                    tier: tiers[tier as keyof typeof tiers],
                    year: year ? Number(year) : null,
                },
            ];
        }),
    );

